import{o as d,a as c,r as l}from"./vue-vendor-xjLLpjf4-1795698964759.js";const p="2026-11-17",h={privacy:{title:"Privacy policy",sections:[{heading:"Data controller",body:"Circuit Court is the controller of the personal data described in this policy. For any question or request, write to support@circuitcourt.com."},{heading:"Data we collect",body:"We process your email address and Firebase identifier, producer profile information (name, address, location, phone, website and business email), the location used for search, the shopping-list content stored in your browser, your feedback messages and the technical logs needed to operate and secure the service."},{heading:"Purposes and legal bases",body:"This data is used to provide the service, authenticate accounts, show nearby producers, answer messages and secure the platform. The legal bases are performance of the contract, our legitimate interest in securing and improving the service, your consent for optional communications and compliance with our legal obligations."},{heading:"Recipients and transfers",body:"Data is accessible to the providers that host and operate the service, including Google Firebase for authentication, GitHub Pages for the static site, ngrok for server access and Mailgun for email delivery. We do not sell your data. Some providers may process data outside the European Union under appropriate contractual safeguards."},{heading:"Retention and deletion",body:"Account data is kept while the service is used. Account deletion is currently a soft delete: the profile is hidden but the row may be retained for security, evidential or legal reasons. You can request full erasure at support@circuitcourt.com. Technical logs are kept for a limited period."},{heading:"Your rights",body:"You have the right to access, rectify, erase, restrict, object and port your data. You can exercise these rights by writing to support@circuitcourt.com. You may also lodge a complaint with the CNIL (www.cnil.fr)."},{heading:"Cookies and local storage",body:"The service uses only necessary local storage: the Firebase session, the selected language, the shopping list and version information. We do not use advertising cookies or analytics tools. If that changes, your consent will be requested before any non-essential storage is set."}]},terms:{title:"Terms of use",sections:[{heading:"The service",body:"Circuit Court is a discovery and price-comparison service for local products. It connects consumers and producers. Circuit Court does not process any sale, order, payment, delivery or reservation."},{heading:"User account",body:"You must provide accurate information, keep your credentials confidential and be at least 16 years old. You are responsible for activity carried out with your account and must report any unauthorised use without delay."},{heading:"Producer obligations",body:"Producers must publish accurate products, prices, quantities and availability, comply with the rules applicable to their products and business, and offer no unlawful goods. They remain solely responsible for the compliance, quality and safety of their products."},{heading:"Acceptable use",body:"You may not scrape data at scale, disrupt the service, impersonate another person, publish false or misleading information, or use the platform for unlawful purposes. An account may be suspended for abuse."},{heading:"Relations between users",body:"Any relationship, reservation or sale between a consumer and a producer is made directly between them. Circuit Court is not a party to those agreements and does not guarantee the availability, price or quality of the products advertised."},{heading:"Liability and intellectual property",body:"The service is provided as is, within the limits of reasonable efforts and mandatory law. Circuit Court's trademarks, text, images and software remain protected. Unauthorised reproduction is prohibited."},{heading:"Changes and governing law",body:"These terms may change; the online version is authoritative. They are governed by French law. For any question, contact support@circuitcourt.com."}]},notice:{title:"Legal notice",sections:[{heading:"Publisher",body:"The site is published by Circuit Court. Contact: support@circuitcourt.com. Registration details and the publisher's postal address are available on request at that address."},{heading:"Publication director",body:"The publication director is the representative of Circuit Court, reachable at support@circuitcourt.com."},{heading:"Hosting",body:"The static site is hosted by GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, USA). The application service is hosted on infrastructure controlled by the publisher and exposed through ngrok."},{heading:"Intellectual property",body:"The site's content, trademarks, text, images and software are protected by intellectual-property law. Unauthorised reproduction or reuse is prohibited."},{heading:"Personal data",body:"The processing of personal data is described in the privacy policy. To exercise your rights, write to support@circuitcourt.com."}]},cookies:{title:"Cookie policy",sections:[{heading:"What we store",body:"Circuit Court uses technical cookies and browser local storage to operate the service. These items are not used to track you for advertising."},{heading:"Essential storage",body:"We store the Firebase authentication session, the selected language, your shopping list, your search preferences and version information. The service cannot work correctly without these items."},{heading:"Analytics and advertising",body:"We currently use no advertising cookies and no analytics tools. If we add them, we will show a consent banner and you will be able to refuse non-essential cookies."},{heading:"Third-party services",body:"Firebase Authentication (Google) may set cookies or local storage needed for sign-in. GitHub Pages and ngrok process technical logs when the site and API are accessed."},{heading:"Managing storage",body:"You can delete cookies and local storage in your browser settings, or sign out to clear the session. Deleting essential storage may require you to sign in again and re-enter your shopping list."}]}},m={updated:p,docs:h},g="2026-11-17",b={privacy:{title:"Politique de confidentialité",sections:[{heading:"Responsable du traitement",body:"Circuit Court est responsable du traitement des données personnelles décrites dans cette politique. Pour toute question ou demande, écrivez à support@circuitcourt.com."},{heading:"Données collectées",body:"Nous traitons votre adresse e-mail et votre identifiant Firebase, les informations de profil des producteurs (nom, adresse, coordonnées, téléphone, site web et e-mail professionnel), la localisation utilisée pour la recherche, le contenu de vos listes de courses stocké dans votre navigateur, vos messages de retour et les journaux techniques nécessaires au fonctionnement et à la sécurité du service."},{heading:"Finalités et bases légales",body:"Ces données servent à fournir le service, authentifier les comptes, afficher les producteurs proches, répondre aux messages et sécuriser la plateforme. Les bases légales sont l'exécution du contrat, notre intérêt légitime à sécuriser et améliorer le service, votre consentement pour les communications facultatives et le respect de nos obligations légales."},{heading:"Destinataires et transferts",body:"Les données sont accessibles aux prestataires qui hébergent et exploitent le service, notamment Google Firebase pour l'authentification, GitHub Pages pour le site statique, ngrok pour l'accès au serveur et Mailgun pour l'envoi des e-mails. Nous ne vendons pas vos données. Certains prestataires peuvent traiter des données hors de l'Union européenne avec des garanties contractuelles appropriées."},{heading:"Conservation et suppression",body:"Les données de compte sont conservées pendant la durée d'utilisation du service. La suppression d'un compte est actuellement un marquage de suppression : le profil est masqué mais la ligne peut être conservée pour des raisons de sécurité, de preuve ou d'obligation légale. Vous pouvez demander l'effacement complet à support@circuitcourt.com. Les journaux techniques sont conservés pour une durée limitée."},{heading:"Vos droits",body:"Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation, d'opposition et de portabilité. Vous pouvez exercer ces droits en écrivant à support@circuitcourt.com. Vous pouvez également introduire une réclamation auprès de la CNIL (www.cnil.fr)."},{heading:"Cookies et stockage local",body:"Le service utilise uniquement un stockage local nécessaire : session Firebase, langue choisie, liste de courses et informations de version. Nous n'utilisons pas de cookies publicitaires ni d'outils de mesure d'audience. Si cela change, votre consentement sera demandé avant tout dépôt non essentiel."}]},terms:{title:"Conditions d'utilisation",sections:[{heading:"Objet du service",body:"Circuit Court est un service de découverte et de comparaison de produits locaux. Il met en relation des consommateurs et des producteurs. Aucune vente, commande, paiement, livraison ou réservation n'est traitée par Circuit Court."},{heading:"Compte utilisateur",body:"Vous devez fournir des informations exactes, garder vos identifiants confidentiels et avoir au moins 16 ans. Vous êtes responsable de l'activité réalisée avec votre compte et devez nous signaler sans délai toute utilisation non autorisée."},{heading:"Obligations des producteurs",body:"Les producteurs doivent publier des produits, prix, quantités et disponibilités exacts, respecter la réglementation applicable à leurs produits et à leur activité, et ne proposer aucun bien illicite. Ils restent seuls responsables de la conformité, de la qualité et de la sécurité de leurs produits."},{heading:"Utilisation acceptable",body:"Il est interdit d'extraire massivement les données, de perturber le service, d'usurper l'identité d'un tiers, de publier des informations fausses ou trompeuses, ou d'utiliser la plateforme à des fins illicites. Un compte peut être suspendu en cas d'abus."},{heading:"Relations entre utilisateurs",body:"Toute relation, réservation ou vente conclue entre un consommateur et un producteur l'est directement entre eux. Circuit Court n'est pas partie à ces accords et ne garantit ni la disponibilité, ni le prix, ni la qualité des produits annoncés."},{heading:"Responsabilité et propriété intellectuelle",body:"Le service est fourni en l'état, dans la limite des efforts raisonnables et des dispositions légales impératives. Les marques, textes, images et logiciels de Circuit Court restent protégés. Toute reproduction non autorisée est interdite."},{heading:"Évolution et droit applicable",body:"Ces conditions peuvent évoluer ; la version en ligne fait foi. Elles sont soumises au droit français. Pour toute question, contactez support@circuitcourt.com."}]},notice:{title:"Mentions légales",sections:[{heading:"Éditeur",body:"Le site est édité par Circuit Court. Contact : support@circuitcourt.com. Les informations d'immatriculation et l'adresse postale de l'éditeur sont disponibles sur demande à cette adresse."},{heading:"Direction de la publication",body:"La direction de la publication est assurée par le représentant de Circuit Court, joignable à support@circuitcourt.com."},{heading:"Hébergement",body:"Le site statique est hébergé par GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, États-Unis). Le service applicatif est hébergé sur une infrastructure contrôlée par l'éditeur et exposé via ngrok."},{heading:"Propriété intellectuelle",body:"Les contenus, marques, textes, images et éléments logiciels du site sont protégés par le droit de la propriété intellectuelle. Toute reproduction ou réutilisation non autorisée est interdite."},{heading:"Données personnelles",body:"Le traitement des données personnelles est décrit dans la politique de confidentialité. Pour exercer vos droits, écrivez à support@circuitcourt.com."}]},cookies:{title:"Politique de cookies",sections:[{heading:"Ce que nous stockons",body:"Circuit Court utilise des cookies techniques et le stockage local du navigateur pour faire fonctionner le service. Ces éléments ne servent pas à vous suivre à des fins publicitaires."},{heading:"Stockage essentiel",body:"Nous stockons la session d'authentification Firebase, la langue sélectionnée, votre liste de courses, vos préférences de recherche et les informations de version. Sans ces éléments, le service ne peut pas fonctionner correctement."},{heading:"Mesure d'audience et publicité",body:"Nous n'utilisons actuellement aucun cookie publicitaire ni outil de mesure d'audience. Si nous en ajoutons, nous afficherons un bandeau de consentement et vous pourrez refuser les cookies non essentiels."},{heading:"Services tiers",body:"Firebase Authentication (Google) peut déposer des cookies ou un stockage local nécessaires à la connexion. GitHub Pages et ngrok traitent des journaux techniques lors de l'accès au site et à l'API."},{heading:"Gérer le stockage",body:"Vous pouvez supprimer les cookies et le stockage local dans les réglages de votre navigateur, ou vous déconnecter pour effacer la session. La suppression du stockage essentiel peut vous obliger à vous reconnecter et à ressaisir votre liste de courses."}]}},y={updated:g,docs:b},k="2026-11-17",f={privacy:{title:"Datenschutzrichtlinie",sections:[{heading:"Datenverantwortlicher",body:"Circuit Court ist für die Verarbeitung der in dieser Richtlinie beschriebenen personenbezogenen Daten verantwortlich. Bei Fragen oder Wünschen schreiben Sie an support@circuitcourt.com."},{heading:"Gesammelte Daten",body:"Wir verarbeiten Ihre E-Mail-Adresse und Firebase-ID, Herstellerprofilinformationen (Name, Adresse, Kontaktdaten, Telefon, Website und geschäftliche E-Mail), den für die Recherche verwendeten Standort, den Inhalt Ihrer in Ihrem Browser gespeicherten Einkaufslisten, Ihre Feedback-Nachrichten und technischen Protokolle, die für den Betrieb und die Sicherheit des Dienstes erforderlich sind."},{heading:"Zwecke und Rechtsgrundlagen",body:"Diese Daten werden verwendet, um den Dienst bereitzustellen, Konten zu authentifizieren, Produzenten in der Nähe anzuzeigen, auf Nachrichten zu antworten und die Plattform zu sichern. Rechtsgrundlagen sind die Vertragserfüllung, unser berechtigtes Interesse an der Sicherung und Verbesserung des Dienstes, Ihre Einwilligung zur optionalen Kommunikation sowie die Einhaltung unserer rechtlichen Verpflichtungen."},{heading:"Empfänger und Überweisungen",body:"Auf die Daten können Anbieter zugreifen, die den Dienst hosten und betreiben, darunter Google Firebase für die Authentifizierung, GitHub Pages für die statische Site, ngrok für den Serverzugriff und Mailgun für den E-Mail-Versand. Wir verkaufen Ihre Daten nicht. Einige Anbieter können mit entsprechenden vertraglichen Garantien Daten außerhalb der Europäischen Union verarbeiten."},{heading:"Aufbewahrung und Löschung",body:"Die Kontodaten werden für die Dauer der Nutzung des Dienstes gespeichert. Das Löschen eines Kontos stellt derzeit eine Löschung dar: Das Profil wird ausgeblendet, die Zeile kann jedoch aus Sicherheits-, Beweisgründen oder rechtlichen Gründen aufbewahrt werden. Sie können bei support@circuitcourt.com eine vollständige Löschung beantragen. Technische Protokolle werden für einen begrenzten Zeitraum aufbewahrt."},{heading:"Ihre Rechte",body:"Sie haben ein Recht auf Auskunft, Berichtigung, Löschung, Einschränkung, Widerspruch und Übertragbarkeit. Sie können diese Rechte ausüben, indem Sie an support@circuitcourt.com schreiben. Sie können eine Beschwerde auch an CNIL (www.cnil.fr) einreichen."},{heading:"Cookies und lokale Speicherung",body:"Der Dienst verwendet nur den erforderlichen lokalen Speicher: Firebase-Sitzung, ausgewählte Sprache, Einkaufsliste und Versionsinformationen. Wir verwenden keine Werbe-Cookies oder Tools zur Zielgruppenmessung. Sollte sich dies ändern, wird Ihr Einverständnis eingeholt, bevor nicht unbedingt erforderliche Einzahlungen vorgenommen werden."}]},terms:{title:"Nutzungsbedingungen",sections:[{heading:"Zweck der Dienstleistung",body:"Circuit Court ist ein lokaler Produkterkennungs- und Vergleichsdienst. Es verbindet Verbraucher und Produzenten. Von Circuit Court werden keine Verkäufe, Bestellungen, Zahlungen, Lieferungen oder Reservierungen bearbeitet."},{heading:"Benutzerkonto",body:"Sie müssen genaue Angaben machen, Ihre Anmeldedaten vertraulich behandeln und mindestens 16 Jahre alt sein. Sie sind für die Aktivitäten verantwortlich, die mit Ihrem Konto stattfinden, und müssen uns unverzüglich über jede unbefugte Nutzung informieren."},{heading:"Pflichten der Produzenten",body:"Hersteller müssen genaue Produkte, Preise, Mengen und Verfügbarkeit veröffentlichen, die für ihre Produkte und ihre Tätigkeit geltenden Vorschriften einhalten und dürfen keine illegalen Waren anbieten. Sie bleiben allein verantwortlich für die Konformität, Qualität und Sicherheit ihrer Produkte."},{heading:"Akzeptable Verwendung",body:"Es ist verboten, massenhaft Daten zu extrahieren, den Dienst zu stören, sich als Dritte auszugeben, falsche oder irreführende Informationen zu veröffentlichen oder die Plattform für illegale Zwecke zu nutzen. Bei Missbrauch kann ein Konto gesperrt werden."},{heading:"Beziehungen zwischen Benutzern",body:"Alle zwischen einem Verbraucher und einem Hersteller geschlossenen Beziehungen, Reservierungen oder Verkäufe werden direkt zwischen ihnen geschlossen. Circuit Court ist nicht Vertragspartei dieser Vereinbarungen und übernimmt keine Garantie für die Verfügbarkeit, den Preis oder die Qualität der beworbenen Produkte."},{heading:"Haftung und geistiges Eigentum",body:"Die Dienstleistung wird im Rahmen des Zumutbaren und der zwingenden gesetzlichen Bestimmungen im Ist-Zustand erbracht. Die Marken, Texte, Bilder und Software von Circuit Court bleiben geschützt. Jede unerlaubte Vervielfältigung ist untersagt."},{heading:"Evolution und geltendes Recht",body:"Diese Bedingungen können sich ändern; Die Online-Version ist authentisch. Sie unterliegen dem französischen Recht. Bei Fragen wenden Sie sich bitte an support@circuitcourt.com."}]},notice:{title:"Rechtliche Hinweise",sections:[{heading:"Herausgeber",body:"Die Website wird von Circuit Court veröffentlicht. Kontakt: support@circuitcourt.com. Anmeldeinformationen und die Postanschrift des Herausgebers erhalten Sie auf Anfrage unter dieser Adresse."},{heading:"Veröffentlichungsrichtung",body:"Die Veröffentlichung wird vom Vertreter von Circuit Court verwaltet, erreichbar unter support@circuitcourt.com."},{heading:"Unterkunft",body:"Die statische Website wird von GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, Vereinigte Staaten) gehostet. Der Anwendungsdienst wird auf einer vom Herausgeber kontrollierten Infrastruktur gehostet und über ngrok verfügbar gemacht."},{heading:"Geistiges Eigentum",body:"Die Inhalte, Marken, Texte, Bilder und Softwareelemente der Website unterliegen dem Schutz des geistigen Eigentums. Jede unerlaubte Vervielfältigung oder Wiederverwendung ist untersagt."},{heading:"Persönliche Daten",body:"Die Verarbeitung personenbezogener Daten ist in der Datenschutzerklärung beschrieben. Um Ihre Rechte auszuüben, schreiben Sie an support@circuitcourt.com."}]},cookies:{title:"Cookie-Richtlinie",sections:[{heading:"Was wir speichern",body:"Circuit Court verwendet für den Betrieb des Dienstes technische Cookies und lokale Browserspeicher. Diese Elemente werden nicht dazu verwendet, Sie zu Werbezwecken zu verfolgen."},{heading:"Unverzichtbarer Speicher",body:"Wir speichern die Firebase-Authentifizierungssitzung, die ausgewählte Sprache, Ihre Einkaufsliste, Sucheinstellungen und Versionsinformationen. Ohne diese Elemente kann der Dienst nicht ordnungsgemäß funktionieren."},{heading:"Zielgruppenmessung und Werbung",body:"Wir verwenden derzeit keine Werbe-Cookies oder Tools zur Zielgruppenmessung. Wenn wir welche hinzufügen, zeigen wir ein Einwilligungsbanner an und Sie können nicht unbedingt erforderliche Cookies ablehnen."},{heading:"Dienste Dritter",body:"Die Firebase-Authentifizierung (Google) setzt möglicherweise Cookies oder lokale Speicher, die für die Anmeldung erforderlich sind. GitHub Pages und ngrok verarbeiten technische Protokolle beim Zugriff auf die Website und die API."},{heading:"Speicher verwalten",body:"Sie können Cookies und lokale Speicherung in Ihren Browsereinstellungen löschen oder sich abmelden, um die Sitzung zu löschen. Wenn Sie wichtigen Speicherplatz entfernen, müssen Sie sich möglicherweise erneut anmelden und Ihre Einkaufsliste erneut eingeben."}]}},v={updated:k,docs:f},C="2026-11-17",w={privacy:{title:"política de privacidad",sections:[{heading:"Responsable del tratamiento",body:"Circuit Court es el responsable del tratamiento de los datos personales descritos en esta política. Para cualquier duda o petición escribir a support@circuitcourt.com."},{heading:"Datos recopilados",body:"Procesamos su dirección de correo electrónico y su ID de Firebase, información del perfil del productor (nombre, dirección, datos de contacto, teléfono, sitio web y correo electrónico comercial), la ubicación utilizada para la investigación, el contenido de sus listas de compras almacenadas en su navegador, sus mensajes de comentarios y los registros técnicos necesarios para el funcionamiento y la seguridad del servicio."},{heading:"Finalidades y bases legales",body:"Estos datos se utilizan para proporcionar el servicio, autenticar cuentas, mostrar productores cercanos, responder mensajes y proteger la plataforma. Las bases legales son la ejecución del contrato, nuestro interés legítimo en asegurar y mejorar el servicio, su consentimiento para comunicaciones opcionales y el cumplimiento de nuestras obligaciones legales."},{heading:"Destinatarios y transferencias",body:"Los datos son accesibles para los proveedores que alojan y operan el servicio, incluidos Google Firebase para autenticación, GitHub Pages para el sitio estático, ngrok para acceso al servidor y Mailgun para envío de correos electrónicos. No vendemos tus datos. Algunos proveedores pueden procesar datos fuera de la Unión Europea con las garantías contractuales adecuadas."},{heading:"Retención y eliminación",body:"Los datos de la cuenta se conservan mientras dure el uso del servicio. Eliminar una cuenta actualmente es una marca de eliminación: el perfil está oculto pero la línea se puede conservar por motivos de seguridad, prueba u obligación legal. Puede solicitar el borrado completo a support@circuitcourt.com. Los registros técnicos se conservan durante un período limitado."},{heading:"Tus derechos",body:"Tienes derecho de acceso, rectificación, supresión, limitación, oposición y portabilidad. Puede ejercer estos derechos escribiendo a support@circuitcourt.com. También puede enviar una queja a CNIL (www.cnil.fr)."},{heading:"Cookies y almacenamiento local",body:"El servicio utiliza sólo el almacenamiento local necesario: sesión Firebase, idioma elegido, lista de compras e información de versión. No utilizamos cookies publicitarias ni herramientas de medición de audiencia. Si esto cambia, se solicitará su consentimiento antes de realizar cualquier depósito no esencial."}]},terms:{title:"Condiciones de uso",sections:[{heading:"Propósito del servicio",body:"Circuit Court es un servicio local de comparación y descubrimiento de productos. Conecta a consumidores y productores. Circuit Court no procesa ventas, pedidos, pagos, entregas o reservas."},{heading:"cuenta de usuario",body:"Debes proporcionar información veraz, mantener tus credenciales confidenciales y tener al menos 16 años. Usted es responsable de la actividad que ocurre con su cuenta y debe notificarnos de inmediato sobre cualquier uso no autorizado."},{heading:"Obligaciones de los productores",body:"Los productores deben publicar productos, precios, cantidades y disponibilidad exactos, cumplir con la normativa aplicable a sus productos y a su actividad, y no ofrecer bienes ilícitos. Siguen siendo los únicos responsables de la conformidad, calidad y seguridad de sus productos."},{heading:"Uso aceptable",body:"Está prohibido extraer datos masivamente, interrumpir el servicio, suplantar a un tercero, publicar información falsa o engañosa o utilizar la plataforma con fines ilícitos. Una cuenta puede suspenderse en caso de abuso."},{heading:"Relaciones entre usuarios",body:"Cualquier relación, reserva o venta celebrada entre un consumidor y un productor se concluye directamente entre ellos. Circuit Court no es parte de estos acuerdos y no garantiza la disponibilidad, el precio o la calidad de los productos anunciados."},{heading:"Responsabilidad y propiedad intelectual",body:"El servicio se proporciona tal cual, dentro de los límites de los esfuerzos razonables y las disposiciones legales obligatorias. Las marcas, textos, imágenes y software de Circuit Court permanecen protegidos. Cualquier reproducción no autorizada está prohibida."},{heading:"Evolución y legislación aplicable",body:"Estas condiciones pueden cambiar; la versión en línea es auténtica. Están sujetos a la ley francesa. Para cualquier duda contacte con support@circuitcourt.com."}]},notice:{title:"Avisos legales",sections:[{heading:"Redactor",body:"El sitio es publicado por Circuit Court. Contacto: support@circuitcourt.com. La información de registro y la dirección postal del editor están disponibles previa solicitud en esta dirección."},{heading:"Dirección de publicación",body:"La publicación está gestionada por el representante de Circuit Court, accesible en support@circuitcourt.com."},{heading:"Alojamiento",body:"El sitio estático está alojado en GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, Estados Unidos). El servicio de la aplicación está alojado en una infraestructura controlada por el editor y expuesta a través de ngrok."},{heading:"Propiedad intelectual",body:"Los contenidos, marcas, textos, imágenes y elementos de software del sitio están protegidos por la ley de propiedad intelectual. Cualquier reproducción o reutilización no autorizada está prohibida."},{heading:"Datos personales",body:"El tratamiento de datos personales se describe en la política de privacidad. Para ejercer sus derechos escriba a support@circuitcourt.com."}]},cookies:{title:"Política de cookies",sections:[{heading:"lo que almacenamos",body:"Circuit Court utiliza cookies técnicas y almacenamiento del navegador local para operar el servicio. Estos elementos no se utilizan para rastrearlo con fines publicitarios."},{heading:"Almacenamiento esencial",body:"Almacenamos la sesión de autenticación Firebase, el idioma seleccionado, su lista de compras, preferencias de búsqueda e información de versión. Sin estos elementos el servicio no puede funcionar correctamente."},{heading:"Medición de audiencia y publicidad.",body:"Actualmente no utilizamos cookies publicitarias ni herramientas de medición de audiencia. Si agregamos alguna, mostraremos un banner de consentimiento y podrá rechazar las cookies no esenciales."},{heading:"Servicios de terceros",body:"La autenticación Firebase (Google) puede establecer cookies o almacenamiento local necesarios para iniciar sesión. GitHub Pages y ngrok procesan registros técnicos al acceder al sitio y a la API."},{heading:"Administrar almacenamiento",body:"Puede eliminar las cookies y el almacenamiento local en la configuración de su navegador, o cerrar sesión para borrar la sesión. Para eliminar el almacenamiento esencial, es posible que tengas que volver a iniciar sesión y volver a ingresar a tu lista de compras."}]}},P={updated:C,docs:w},z="2026-11-17",A={privacy:{title:"política de Privacidade",sections:[{heading:"Controlador de dados",body:"A Circuit Court é responsável pelo tratamento dos dados pessoais descritos nesta política. Para qualquer dúvida ou solicitação, escreva para support@circuitcourt.com."},{heading:"Dados coletados",body:"Processamos seu endereço de e-mail e ID Firebase, informações de perfil de produtor (nome, endereço, dados de contato, telefone, site e e-mail comercial), local utilizado para pesquisa, conteúdo de suas listas de compras armazenadas em seu navegador, suas mensagens de feedback e registros técnicos necessários para a operação e segurança do serviço."},{heading:"Finalidades e bases legais",body:"Esses dados são usados para fornecer o serviço, autenticar contas, exibir produtores próximos, responder mensagens e proteger a plataforma. As bases jurídicas são a execução do contrato, o nosso interesse legítimo em garantir e melhorar o serviço, o seu consentimento para comunicações opcionais e o cumprimento das nossas obrigações legais."},{heading:"Destinatários e transferências",body:"Os dados são acessíveis aos provedores que hospedam e operam o serviço, incluindo Google Firebase para autenticação, GitHub Pages para site estático, ngrok para acesso ao servidor e Mailgun para envio de e-mails. Não vendemos seus dados. Alguns fornecedores podem processar dados fora da União Europeia com garantias contratuais adequadas."},{heading:"Retenção e exclusão",body:"Os dados da conta são retidos durante a utilização do serviço. A exclusão de uma conta é atualmente uma marcação de exclusão: o perfil fica oculto, mas a linha pode ser mantida por motivos de segurança, prova ou obrigação legal. Você pode solicitar o apagamento completo de support@circuitcourt.com. Os registros técnicos são mantidos por um período limitado."},{heading:"Seus direitos",body:"Tem direito de acesso, retificação, apagamento, limitação, oposição e portabilidade. Você pode exercer esses direitos escrevendo para support@circuitcourt.com. Você também pode enviar uma reclamação para CNIL (www.cnil.fr)."},{heading:"Cookies e armazenamento local",body:"O serviço utiliza apenas o armazenamento local necessário: sessão Firebase, idioma escolhido, lista de compras e informações de versão. Não utilizamos cookies publicitários nem ferramentas de medição de audiência. Se isso mudar, seu consentimento será solicitado antes que quaisquer depósitos não essenciais sejam feitos."}]},terms:{title:"Termos de Uso",sections:[{heading:"Objetivo do serviço",body:"Circuit Court é um serviço local de descoberta e comparação de produtos. Ele conecta consumidores e produtores. Nenhuma venda, pedido, pagamento, entrega ou reserva é processado pela Circuit Court."},{heading:"Conta de usuário",body:"Você deve fornecer informações precisas, manter suas credenciais confidenciais e ter pelo menos 16 anos de idade. Você é responsável pela atividade que ocorre com sua conta e deve nos notificar imediatamente sobre qualquer uso não autorizado."},{heading:"Obrigações dos produtores",body:"Os produtores devem publicar produtos, preços, quantidades e disponibilidade exatos, cumprir a regulamentação aplicável aos seus produtos e à sua atividade e não oferecer quaisquer bens ilícitos. Eles permanecem os únicos responsáveis ​​pela conformidade, qualidade e segurança dos seus produtos."},{heading:"Uso aceitável",body:"É proibido extrair dados em massa, interromper o serviço, fazer-se passar por terceiros, publicar informações falsas ou enganosas ou utilizar a plataforma para fins ilícitos. Uma conta pode ser suspensa em caso de abuso."},{heading:"Relacionamentos entre usuários",body:"Qualquer relação, reserva ou venda celebrada entre um consumidor e um produtor é celebrada diretamente entre eles. Circuit Court não faz parte destes acordos e não garante a disponibilidade, preço ou qualidade dos produtos anunciados."},{heading:"Responsabilidade e propriedade intelectual",body:"O serviço é prestado tal como está, dentro dos limites dos esforços razoáveis e das disposições legais obrigatórias. As marcas, textos, imagens e software da Circuit Court permanecem protegidos. Qualquer reprodução não autorizada é proibida."},{heading:"Evolução e lei aplicável",body:"Estas condições podem mudar; a versão online é autêntica. Eles estão sujeitos à lei francesa. Para qualquer dúvida, entre em contato com support@circuitcourt.com."}]},notice:{title:"Avisos legais",sections:[{heading:"Editor",body:"O site é publicado pela Circuit Court. Contato: support@circuitcourt.com. As informações de registro e o endereço postal do editor estão disponíveis mediante solicitação neste endereço."},{heading:"Direção de publicação",body:"A publicação é gerenciada pelo representante da Circuit Court, acessível em support@circuitcourt.com."},{heading:"Alojamento",body:"O site estático é hospedado por GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, Estados Unidos). O serviço de aplicação é hospedado em uma infraestrutura controlada pelo editor e exposta via ngrok."},{heading:"Propriedade intelectual",body:"Os conteúdos, marcas, textos, imagens e elementos de software do site estão protegidos pela lei de propriedade intelectual. Qualquer reprodução ou reutilização não autorizada é proibida."},{heading:"Dados pessoais",body:"O tratamento de dados pessoais está descrito na política de privacidade. Para exercer os seus direitos, escreva para support@circuitcourt.com."}]},cookies:{title:"Política de cookies",sections:[{heading:"O que armazenamos",body:"Circuit Court usa cookies técnicos e armazenamento local do navegador para operar o serviço. Esses elementos não são usados ​​para rastreá-lo para fins publicitários."},{heading:"Armazenamento essencial",body:"Armazenamos a sessão de autenticação Firebase, o idioma selecionado, sua lista de compras, preferências de pesquisa e informações de versão. Sem estes elementos, o serviço não pode funcionar adequadamente."},{heading:"Medição de audiência e publicidade",body:"Atualmente não utilizamos quaisquer cookies publicitários ou ferramentas de medição de audiência. Se adicionarmos algum, exibiremos um banner de consentimento e você poderá recusar cookies não essenciais."},{heading:"Serviços de terceiros",body:"A autenticação Firebase (Google) pode definir cookies ou armazenamento local necessário para login. GitHub Pages e ngrok processam logs técnicos ao acessar o site e a API."},{heading:"Gerenciar armazenamento",body:"Você pode excluir cookies e armazenamento local nas configurações do seu navegador ou sair para limpar a sessão. A remoção do armazenamento essencial pode exigir que você faça login novamente e insira novamente sua lista de compras."}]}},E={updated:z,docs:A},S="2026-11-17",D={privacy:{title:"Kebijakan Privasi",sections:[{heading:"Pengontrol data",body:"Circuit Court bertanggung jawab untuk memproses data pribadi yang dijelaskan dalam kebijakan ini. Untuk pertanyaan atau permintaan apa pun, tulis ke support@circuitcourt.com."},{heading:"Data dikumpulkan",body:"Kami memproses alamat email Anda dan ID Firebase, informasi profil produsen (nama, alamat, rincian kontak, telepon, situs web dan email bisnis), lokasi yang digunakan untuk penelitian, konten daftar belanjaan Anda yang disimpan di browser Anda, pesan umpan balik Anda dan log teknis yang diperlukan untuk pengoperasian dan keamanan layanan."},{heading:"Tujuan dan dasar hukum",body:"Data ini digunakan untuk menyediakan layanan, mengautentikasi akun, menampilkan produsen terdekat, merespons pesan, dan mengamankan platform. Dasar hukumnya adalah pelaksanaan kontrak, kepentingan sah kami dalam mengamankan dan meningkatkan layanan, persetujuan Anda untuk komunikasi opsional, dan kepatuhan terhadap kewajiban hukum kami."},{heading:"Penerima dan transfer",body:"Data dapat diakses oleh penyedia yang menghosting dan mengoperasikan layanan, termasuk Google Firebase untuk otentikasi, GitHub Pages untuk situs statis, ngrok untuk akses server dan Mailgun untuk mengirim email. Kami tidak menjual data Anda. Beberapa penyedia mungkin memproses data di luar Uni Eropa dengan jaminan kontrak yang sesuai."},{heading:"Retensi dan penghapusan",body:"Data akun disimpan selama penggunaan layanan. Menghapus akun saat ini merupakan tanda penghapusan: profil disembunyikan tetapi garis tersebut dapat dipertahankan karena alasan keamanan, bukti, atau kewajiban hukum. Anda dapat meminta penghapusan total dari support@circuitcourt.com. Log teknis disimpan untuk jangka waktu terbatas."},{heading:"Hak Anda",body:"Anda memiliki hak akses, perbaikan, penghapusan, pembatasan, penolakan dan portabilitas. Anda dapat menggunakan hak ini dengan menulis ke support@circuitcourt.com. Anda juga dapat menyampaikan keluhan ke CNIL (www.cnil.fr)."},{heading:"Cookie dan penyimpanan lokal",body:"Layanan ini hanya menggunakan penyimpanan lokal yang diperlukan: sesi Firebase, bahasa yang dipilih, daftar belanja, dan informasi versi. Kami tidak menggunakan cookie iklan atau alat pengukuran audiens. Jika hal ini berubah, persetujuan Anda akan diminta sebelum setoran yang tidak penting dilakukan."}]},terms:{title:"Ketentuan Penggunaan",sections:[{heading:"Tujuan layanan",body:"Circuit Court adalah layanan penemuan dan perbandingan produk lokal. Ini menghubungkan konsumen dan produsen. Tidak ada penjualan, pesanan, pembayaran, pengiriman atau reservasi yang diproses oleh Circuit Court."},{heading:"Akun pengguna",body:"Anda harus memberikan informasi yang akurat, menjaga kerahasiaan kredensial Anda dan berusia minimal 16 tahun. Anda bertanggung jawab atas aktivitas yang terjadi pada akun Anda dan harus segera memberi tahu kami jika ada penggunaan tidak sah."},{heading:"Kewajiban produsen",body:"Produsen harus mempublikasikan produk, harga, jumlah dan ketersediaan secara akurat, mematuhi peraturan yang berlaku terhadap produk dan aktivitasnya, serta tidak menawarkan barang terlarang. Mereka tetap bertanggung jawab penuh atas kesesuaian, kualitas dan keamanan produk mereka."},{heading:"Penggunaan yang dapat diterima",body:"Dilarang mengekstraksi data secara besar-besaran, mengganggu layanan, menyamar sebagai pihak ketiga, mempublikasikan informasi palsu atau menyesatkan, atau menggunakan platform untuk tujuan terlarang. Sebuah akun dapat ditangguhkan jika terjadi penyalahgunaan."},{heading:"Hubungan antar pengguna",body:"Setiap hubungan, pemesanan atau penjualan yang dilakukan antara konsumen dan produsen dilakukan secara langsung di antara mereka. Circuit Court bukan merupakan pihak dalam perjanjian ini dan tidak menjamin ketersediaan, harga atau kualitas produk yang diiklankan."},{heading:"Kewajiban dan kekayaan intelektual",body:"Layanan ini diberikan apa adanya, dalam batas upaya wajar dan ketentuan hukum wajib. Merek, teks, gambar, dan perangkat lunak Circuit Court tetap terlindungi. Dilarang melakukan reproduksi tanpa izin."},{heading:"Evolusi dan hukum yang berlaku",body:"Kondisi ini dapat berubah; versi online adalah asli. Mereka tunduk pada hukum Perancis. Untuk pertanyaan apa pun, hubungi support@circuitcourt.com."}]},notice:{title:"Pemberitahuan hukum",sections:[{heading:"Penyunting",body:"Situs ini diterbitkan oleh Circuit Court. Hubungi: support@circuitcourt.com. Informasi pendaftaran dan alamat pos penerbit tersedia berdasarkan permintaan di alamat ini."},{heading:"Arah publikasi",body:"Publikasi ini dikelola oleh perwakilan Circuit Court, dapat dihubungi di support@circuitcourt.com."},{heading:"Akomodasi",body:"Situs statis dihosting oleh GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, Amerika Serikat). Layanan aplikasi dihosting pada infrastruktur yang dikendalikan oleh penerbit dan diekspos melalui ngrok."},{heading:"Kekayaan intelektual",body:"Konten, merek, teks, gambar, dan elemen perangkat lunak situs dilindungi oleh undang-undang kekayaan intelektual. Dilarang memperbanyak atau menggunakan kembali tanpa izin."},{heading:"Data pribadi",body:"Pemrosesan data pribadi dijelaskan dalam kebijakan privasi. Untuk menggunakan hak Anda, kirim surat ke support@circuitcourt.com."}]},cookies:{title:"Kebijakan cookie",sections:[{heading:"Apa yang kami simpan",body:"Circuit Court menggunakan cookie teknis dan penyimpanan browser lokal untuk mengoperasikan layanan. Elemen-elemen ini tidak digunakan untuk melacak Anda untuk tujuan periklanan."},{heading:"Penyimpanan Penting",body:"Kami menyimpan sesi otentikasi Firebase, bahasa yang dipilih, daftar belanja Anda, preferensi pencarian, dan informasi versi. Tanpa unsur-unsur tersebut, pelayanan tidak dapat berfungsi dengan baik."},{heading:"Pengukuran audiens dan periklanan",body:"Saat ini kami tidak menggunakan cookie iklan atau alat pengukuran audiens apa pun. Jika kami menambahkannya, kami akan menampilkan spanduk persetujuan dan Anda dapat menolak cookie yang tidak penting."},{heading:"Layanan pihak ketiga",body:"Otentikasi Firebase (Google) dapat mengatur cookie atau penyimpanan lokal yang diperlukan untuk login. GitHub Pages dan ngrok memproses log teknis saat mengakses situs dan API."},{heading:"Kelola penyimpanan",body:"Anda dapat menghapus cookie dan penyimpanan lokal di pengaturan browser Anda, atau keluar untuk menghapus sesi. Menghapus penyimpanan penting mungkin mengharuskan Anda masuk kembali dan masuk kembali ke daftar belanjaan Anda."}]}},F={updated:S,docs:D},G="2026-11-17",q={privacy:{title:"プライバシーポリシー",sections:[{heading:"データコントローラー",body:"Circuit Court は、このポリシーに記載されている個人データの処理に責任を負います。ご質問やご要望がございましたら、support@circuitcourt.com までご連絡ください。"},{heading:"収集されたデータ",body:"当社は、お客様の電子メール アドレスと Firebase ID、プロデューサー プロフィール情報 (名前、住所、連絡先詳細、電話、ウェブサイト、ビジネス用電子メール)、調査に使用された場所、ブラウザーに保存されているショッピング リストの内容、サービスの運用とセキュリティに必要なフィードバック メッセージおよび技術ログを処理します。"},{heading:"目的と法的根拠",body:"このデータは、サービスの提供、アカウントの認証、近くのプロデューサーの表示、メッセージへの応答、プラットフォームの保護に使用されます。法的根拠は、契約の履行、サービスの確保と改善に対する当社の正当な利益、オプションの通信に対するお客様の同意、および当社の法的義務の遵守です。"},{heading:"受信者と転送",body:"データは、認証用の Google Firebase、静的サイト用の GitHub Pages、サーバー アクセス用の ngrok、電子メール送信用の Mailgun など、サービスをホストおよび運用するプロバイダーにアクセスできます。私たちはあなたのデータを販売しません。一部のプロバイダーは、適切な契約上の保証を付けて欧州連合外のデータを処理する場合があります。"},{heading:"保存と削除",body:"アカウントデータは、サービスの使用期間中保持されます。現在、アカウントの削除は削除のマークです。プロフィールは非表示になりますが、セキュリティ、証拠、または法的義務の理由からラインは保持される場合があります。 support@circuitcourt.com から完全消去をリクエストできます。技術ログは限られた期間保存されます。"},{heading:"あなたの権利",body:"あなたには、アクセス、修正、消去、制限、異議申し立て、およびポータビリティの権利があります。これらの権利は、support@circuitcourt.com に書き込むことで行使できます。 CNIL (www.cnil.fr) に苦情を提出することもできます。"},{heading:"Cookie とローカル ストレージ",body:"このサービスは、必要なローカル ストレージ (Firebase セッション、選択した言語、ショッピング リスト、バージョン情報) のみを使用します。当社は広告 Cookie や視聴者測定ツールを使用しません。これが変更された場合は、不要な入金が行われる前に同意が求められます。"}]},terms:{title:"利用規約",sections:[{heading:"サービスの目的",body:"Circuit Court は、ローカル製品の発見および比較サービスです。消費者と生産者を結びます。 Circuit Court では、販売、注文、支払い、配達、予約は処理されません。"},{heading:"ユーザーアカウント",body:"正確な情報を提供し、資格情報を秘密にし、16 歳以上である必要があります。あなたは自分のアカウントで発生する活動に対して責任を負い、不正使用があった場合は直ちに当社に通知する必要があります。"},{heading:"生産者の義務",body:"生産者は、正確な製品、価格、数量、入手可能性を公表し、自社の製品とその活動に適用される規制を遵守し、違法な商品を提供してはなりません。彼らは自社製品の適合性、品質、安全性について単独で責任を負います。"},{heading:"許容される使用方法",body:"大規模なデータの抽出、サービスの中断、第三者になりすます、虚偽または誤解を招く情報の公開、またはプラットフォームを違法な目的で使用することは禁止されています。不正行為があった場合、アカウントが停止される場合があります。"},{heading:"ユーザー間の関係",body:"消費者と生産者の間で締結される関係、予約、または販売は、消費者と生産者の間で直接締結されます。 Circuit Court はこれらの契約の当事者ではなく、宣伝されている製品の入手可能性、価格、品質を保証しません。"},{heading:"責任と知的財産",body:"サービスは、合理的な努力と強制的な法的規定の範囲内で、現状のまま提供されます。 Circuit Court のブランド、テキスト、画像、ソフトウェアは引き続き保護されます。いかなる無断転載も禁止します。"},{heading:"進化と適用法",body:"これらの条件は変更される可能性があります。オンライン版は本物です。これらはフランスの法律の対象となります。ご質問がある場合は、support@circuitcourt.com までお問い合わせください。"}]},notice:{title:"法的通知",sections:[{heading:"編集者",body:"このサイトはCircuit Courtによって公開されています。連絡先: support@circuitcourt.com。登録情報と発行者の住所は、リクエストに応じてこのアドレスから入手できます。"},{heading:"出版方向",body:"この出版物は、Circuit Court の代表者によって管理されており、support@circuitcourt.com で連絡できます。"},{heading:"宿泊施設",body:"静的サイトは、GitHub Pages (GitHub Inc.、88 Colin P Kelly Jr St、San Francisco、CA 94107、United States) によってホストされています。アプリケーション サービスは、発行者によって制御されるインフラストラクチャ上でホストされ、ngrok 経由で公開されます。"},{heading:"知的財産",body:"サイトのコンテンツ、ブランド、テキスト、画像、およびソフトウェア要素は、知的財産法によって保護されています。無断転載、再利用を禁止します。"},{heading:"個人データ",body:"個人データの処理についてはプライバシー ポリシーに記載されています。権利を行使するには、support@circuitcourt.com に手紙を書いてください。"}]},cookies:{title:"クッキーポリシー",sections:[{heading:"私たちが保管するもの",body:"Circuit Court は、テクニカル Cookie とローカル ブラウザ ストレージを使用してサービスを運営します。これらの要素は、広告目的でお客様を追跡するために使用されるものではありません。"},{heading:"必須のストレージ",body:"Firebase 認証セッション、選択した言語、ショッピング リスト、検索設定、バージョン情報を保存します。これらの要素がなければ、サービスは適切に機能できません。"},{heading:"視聴者数の測定と広告",body:"現在、当社は広告 Cookie や視聴者測定ツールを使用していません。追加する場合は同意バナーが表示され、必須でない Cookie を拒否することができます。"},{heading:"サードパーティのサービス",body:"Firebase 認証 (Google) では、ログインに必要な Cookie またはローカル ストレージが設定される場合があります。 GitHub Pages および ngrok は、サイトおよび API にアクセスするときに技術ログを処理します。"},{heading:"ストレージの管理",body:"ブラウザの設定で Cookie とローカル ストレージを削除するか、ログアウトしてセッションをクリアできます。重要なストレージを削除するには、再度ログインしてショッピング リストを再入力する必要がある場合があります。"}]}},I={updated:G,docs:q},j="2026-11-17",T={privacy:{title:"隐私政策",sections:[{heading:"数据控制者",body:"Circuit Court 负责处理本政策中所述的个人数据。如有任何疑问或要求，请写信至 support@circuitcourt.com。"},{heading:"收集的数据",body:"我们处理您的电子邮件地址和 Firebase ID、生产商资料信息（姓名、地址、联系方式、电话、网站和商务电子邮件）、用于研究的位置、浏览器中存储的购物清单内容、您的反馈消息以及服务运行和安全所需的技术日志。"},{heading:"目的和法律依据",body:"这些数据用于提供服务、验证帐户、显示附近的生产者、响应消息和保护平台。法律依据是合同的履行、我们在确保和改进服务方面的合法利益、您对可选通信的同意以及遵守我们的法律义务。"},{heading:"接收者和转移",body:"托管和运营该服务的提供商可以访问这些数据，包括用于身份验证的 Google Firebase、用于静态站点的 GitHub Pages、用于服务器访问的 ngrok 以及用于发送电子邮件的 Mailgun。我们不会出售您的数据。一些提供商可能会在欧盟以外的地方处理数据，并提供适当的合同保证。"},{heading:"保留和删除",body:"帐户数据在使用服务期间保留。删除帐户目前是一种删除标记：个人资料被隐藏，但出于安全、证据或法律义务的原因可能会保留该行。您可以向 support@circuitcourt.com 请求完全删除。技术日志的保存期限有限。"},{heading:"您的权利",body:"您拥有访问、更正、删除、限制、反对和迁移的权利。您可以通过写信给 support@circuitcourt.com 来行使这些权利。您也可以向CNIL（www.cnil.fr）提交投诉。"},{heading:"Cookie 和本地存储",body:"该服务仅使用必要的本地存储：Firebase 会话、所选语言、购物清单和版本信息。我们不使用广告 cookie 或受众测量工具。如果情况发生变化，在进行任何非必要存款之前将征求您的同意。"}]},terms:{title:"使用条款",sections:[{heading:"服务宗旨",body:"Circuit Court 是本地产品发现和比较服务。它连接消费者和生产者。 Circuit Court 不处理任何销售、订单、付款、交付或预订。"},{heading:"用户帐号",body:"您必须提供准确的信息、对您的凭据保密并且年满 16 岁。您对您的帐户发生的活动负责，并且必须立即通知我们任何未经授权的使用。"},{heading:"生产者的义务",body:"生产商必须公布准确的产品、价格、数量和供货情况，遵守适用于其产品及其活动的法规，并且不得提供任何非法商品。他们仍然对其产品的合规性、质量和安全负全部责任。"},{heading:"可接受的使用",body:"禁止大量提取数据、破坏服务、冒充第三方、发布虚假或误导性信息或将平台用于非法目的。如果发生滥用行为，帐户可能会被暂停。"},{heading:"用户之间的关系",body:"消费者和生产者之间达成的任何关系、预订或销售都是他们之间直接达成的。 Circuit Court 不是这些协议的一方，也不保证所宣传产品的可用性、价格或质量。"},{heading:"责任和知识产权",body:"该服务在合理努力和强制性法律规定的范围内按原样提供。 Circuit Court 的品牌、文字、图像和软件仍然受到保护。禁止任何未经授权的复制。"},{heading:"演变和适用法律",body:"这些条件可能会改变；网络版是正版的。他们受法国法律管辖。如有任何疑问，请联系support@circuitcourt.com。"}]},notice:{title:"法律声明",sections:[{heading:"编辑",body:"该网站由Circuit Court 发布。联系方式：support@circuitcourt.com。可通过此地址索取注册信息和出版商的邮寄地址。"},{heading:"出版方向",body:"该出版物由 Circuit Court 的代表管理，可通过 support@circuitcourt.com 联系。"},{heading:"住宿",body:"该静态站点由 GitHub Pages（GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, United States）托管。应用程序服务托管在由发布者控制的基础设施上，并通过 ngrok 公开。"},{heading:"知识产权",body:"网站的内容、品牌、文本、图像和软件元素均受知识产权法保护。禁止任何未经授权的复制或再利用。"},{heading:"个人资料",body:"隐私政策中描述了个人数据的处理。要行使您的权利，请写信至 support@circuitcourt.com。"}]},cookies:{title:"Cookie 政策",sections:[{heading:"我们储存什么",body:"Circuit Court 使用技术 cookie 和本地浏览器存储来运营服务。这些元素不会出于广告目的而用于跟踪您。"},{heading:"基本存储",body:"我们存储 Firebase 身份验证会话、所选语言、您的购物清单、搜索首选项和版本信息。如果没有这些元素，服务就无法正常运行。"},{heading:"受众测量和广告",body:"我们目前不使用任何广告 cookie 或受众测量工具。如果我们添加任何cookie，我们将显示同意横幅，您可以拒绝非必要的cookie。"},{heading:"第三方服务",body:"Firebase 身份验证（Google）可能会设置登录所需的 cookie 或本地存储。 GitHub Pages 和 ngrok 在访问站点和 API 时处理技术日志。"},{heading:"管理存储",body:"您可以在浏览器设置中删除 Cookie 和本地存储，或注销以清除会话。删除必要的存储空间可能需要您重新登录并重新输入您的购物清单。"}]}},H={updated:j,docs:T},L="2026-11-17",x={privacy:{title:"سياسة الخصوصية",sections:[{heading:"مراقب البيانات",body:"Circuit Court مسؤولة عن معالجة البيانات الشخصية الموضحة في هذه السياسة. لأية أسئلة أو طلبات، اكتب إلى support@circuitcourt.com."},{heading:"البيانات التي تم جمعها",body:"نقوم بمعالجة عنوان بريدك الإلكتروني ومعرف Firebase ومعلومات ملف تعريف المنتج (الاسم والعنوان وتفاصيل الاتصال والهاتف والموقع الإلكتروني والبريد الإلكتروني الخاص بالعمل)، والموقع المستخدم للبحث، ومحتوى قوائم التسوق الخاصة بك المخزنة في متصفحك، ورسائل تعليقاتك والسجلات الفنية اللازمة لتشغيل الخدمة وأمانها."},{heading:"الأغراض والأسس القانونية",body:"يتم استخدام هذه البيانات لتقديم الخدمة ومصادقة الحسابات وعرض المنتجين القريبين والرد على الرسائل وتأمين المنصة. تتمثل الأسس القانونية في تنفيذ العقد، ومصلحتنا المشروعة في تأمين الخدمة وتحسينها، وموافقتك على الاتصالات الاختيارية، والامتثال لالتزاماتنا القانونية."},{heading:"المستلمون والتحويلات",body:"يمكن الوصول إلى البيانات لمقدمي الخدمة الذين يستضيفون الخدمة ويقومون بتشغيلها، بما في ذلك Google Firebase للمصادقة، وGitHub Pages للموقع الثابت، وngrok للوصول إلى الخادم، وMailgun لإرسال رسائل البريد الإلكتروني. نحن لا نبيع بياناتك. قد يقوم بعض مقدمي الخدمة بمعالجة البيانات خارج الاتحاد الأوروبي مع ضمانات تعاقدية مناسبة."},{heading:"الاحتفاظ والحذف",body:"يتم الاحتفاظ ببيانات الحساب طوال مدة استخدام الخدمة. يعد حذف الحساب حاليًا بمثابة علامة للحذف: الملف الشخصي مخفي ولكن قد يتم الاحتفاظ بالسطر لأسباب أمنية أو دليل أو التزام قانوني. يمكنك طلب المحو الكامل من support@circuitcourt.com. يتم الاحتفاظ بالسجلات الفنية لفترة محدودة."},{heading:"حقوقك",body:"لديك الحق في الوصول والتصحيح والمحو والتقييد والمعارضة وقابلية النقل. يمكنك ممارسة هذه الحقوق عن طريق الكتابة إلى support@circuitcourt.com. يمكنك أيضًا تقديم شكوى إلى CNIL (www.cnil.fr)."},{heading:"ملفات تعريف الارتباط والتخزين المحلي",body:"تستخدم الخدمة فقط التخزين المحلي الضروري: جلسة Firebase واللغة المختارة وقائمة التسوق ومعلومات الإصدار. نحن لا نستخدم ملفات تعريف الارتباط الإعلانية أو أدوات قياس الجمهور. إذا تغير هذا، فسيتم طلب موافقتك قبل إجراء أي إيداعات غير ضرورية."}]},terms:{title:"شروط الاستخدام",sections:[{heading:"الغرض من الخدمة",body:"Circuit Court هي خدمة اكتشاف ومقارنة المنتجات المحلية. فهو يربط بين المستهلكين والمنتجين. لا تتم معالجة أي مبيعات أو طلبات أو مدفوعات أو عمليات تسليم أو حجوزات بواسطة Circuit Court."},{heading:"حساب المستخدم",body:"يجب عليك تقديم معلومات دقيقة والحفاظ على سرية بيانات الاعتماد الخاصة بك وأن يكون عمرك 16 عامًا على الأقل. أنت مسؤول عن النشاط الذي يحدث في حسابك ويجب عليك إخطارنا على الفور بأي استخدام غير مصرح به."},{heading:"التزامات المنتجين",body:"يجب على المنتجين نشر المنتجات والأسعار والكميات والتوفر بشكل دقيق، والالتزام باللوائح المطبقة على منتجاتهم ونشاطهم، وعدم تقديم أي سلع غير مشروعة. يظلون مسؤولين وحدهم عن مطابقة منتجاتهم وجودتها وسلامتها."},{heading:"الاستخدام المقبول",body:"يُحظر استخراج البيانات على نطاق واسع، أو تعطيل الخدمة، أو انتحال شخصية طرف ثالث، أو نشر معلومات كاذبة أو مضللة، أو استخدام المنصة لأغراض غير مشروعة. قد يتم تعليق الحساب في حالة إساءة الاستخدام."},{heading:"العلاقات بين المستخدمين",body:"أي علاقة أو حجز أو بيع يتم بين المستهلك والمنتج يتم بشكل مباشر بينهما. Circuit Court ليست طرفًا في هذه الاتفاقيات ولا تضمن توفر المنتجات المعلن عنها أو سعرها أو جودتها."},{heading:"المسؤولية والملكية الفكرية",body:"يتم تقديم الخدمة كما هي، وفي حدود الجهود المعقولة والأحكام القانونية الإلزامية. تظل العلامات التجارية والنصوص والصور والبرامج الخاصة بـ Circuit Court محمية. يحظر أي النسخ غير المصرح به."},{heading:"التطور والقانون الواجب التطبيق",body:"قد تتغير هذه الشروط؛ النسخة الإلكترونية أصلية. وهم يخضعون للقانون الفرنسي. لأية أسئلة، اتصل بـ support@circuitcourt.com."}]},notice:{title:"إشعارات قانونية",sections:[{heading:"محرر",body:"يتم نشر الموقع بواسطة Circuit Court. جهة الاتصال: support@circuitcourt.com. معلومات التسجيل والعنوان البريدي للناشر متاحة عند الطلب على هذا العنوان."},{heading:"اتجاه النشر",body:"تتم إدارة المنشور من قبل ممثل Circuit Court، ويمكن الوصول إليه على support@circuitcourt.com."},{heading:"الإقامة",body:"تتم استضافة الموقع الثابت بواسطة GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, San Francisco, CA 94107, United States). تتم استضافة خدمة التطبيق على بنية تحتية يتحكم فيها الناشر ويتم عرضها عبر ngrok."},{heading:"الملكية الفكرية",body:"إن المحتويات والعلامات التجارية والنصوص والصور والعناصر البرمجية للموقع محمية بموجب قانون الملكية الفكرية. يحظر أي نسخ أو إعادة استخدام غير مصرح بها."},{heading:"البيانات الشخصية",body:"يتم وصف معالجة البيانات الشخصية في سياسة الخصوصية. لممارسة حقوقك، اكتب إلى support@circuitcourt.com."}]},cookies:{title:"سياسة ملفات تعريف الارتباط",sections:[{heading:"ما نقوم بتخزينه",body:"تستخدم Circuit Court ملفات تعريف الارتباط التقنية وتخزين المتصفح المحلي لتشغيل الخدمة. لا يتم استخدام هذه العناصر لتتبعك لأغراض إعلانية."},{heading:"التخزين الأساسي",body:"نقوم بتخزين جلسة مصادقة Firebase واللغة المحددة وقائمة التسوق الخاصة بك وتفضيلات البحث ومعلومات الإصدار. وبدون هذه العناصر، لا يمكن للخدمة أن تعمل بشكل صحيح."},{heading:"قياس الجمهور والإعلان",body:"نحن لا نستخدم حاليًا أي ملفات تعريف ارتباط إعلانية أو أدوات لقياس الجمهور. إذا أضفنا أيًا منها، فسنعرض لافتة موافقة ويمكنك رفض ملفات تعريف الارتباط غير الضرورية."},{heading:"خدمات الطرف الثالث",body:"قد تقوم مصادقة Firebase (Google) بتعيين ملفات تعريف الارتباط أو التخزين المحلي اللازم لتسجيل الدخول. يقوم كل من GitHub Pages وngrok بمعالجة السجلات الفنية عند الوصول إلى الموقع وواجهة برمجة التطبيقات."},{heading:"إدارة التخزين",body:"يمكنك حذف ملفات تعريف الارتباط والتخزين المحلي في إعدادات المتصفح الخاص بك، أو تسجيل الخروج لمسح الجلسة. قد تتطلب إزالة مساحة التخزين الأساسية منك تسجيل الدخول مرة أخرى وإعادة إدخال قائمة التسوق الخاصة بك."}]}},V={updated:L,docs:x},K="2026-11-17",U={privacy:{title:"политика конфиденциальности",sections:[{heading:"Контроллер данных",body:"Circuit Court несет ответственность за обработку персональных данных, описанных в настоящей политике. По любым вопросам или пожеланиям пишите на support@circuitcourt.com."},{heading:"Собранные данные",body:"Мы обрабатываем ваш адрес электронной почты и идентификатор Firebase, информацию профиля производителя (имя, адрес, контактные данные, телефон, веб-сайт и рабочий адрес электронной почты), местоположение, используемое для исследования, содержимое ваших списков покупок, хранящихся в вашем браузере, ваши сообщения обратной связи и технические журналы, необходимые для работы и безопасности службы."},{heading:"Цели и правовые основы",body:"Эти данные используются для предоставления услуги, аутентификации учетных записей, отображения ближайших производителей, ответа на сообщения и обеспечения безопасности платформы. Правовыми основаниями являются выполнение договора, наш законный интерес в обеспечении безопасности и улучшении услуги, ваше согласие на необязательные сообщения и соблюдение наших юридических обязательств."},{heading:"Получатели и переводы",body:"Данные доступны провайдерам, которые размещают и управляют службой, включая Google Firebase для аутентификации, GitHub Pages для статического сайта, ngrok для доступа к серверу и Mailgun для отправки электронных писем. Мы не продаем ваши данные. Некоторые поставщики могут обрабатывать данные за пределами Европейского Союза при наличии соответствующих договорных гарантий."},{heading:"Хранение и удаление",body:"Данные учетной записи сохраняются на протяжении всего срока использования услуги. Удаление учетной записи в настоящее время является признаком удаления: профиль скрыт, но линия может быть сохранена по соображениям безопасности, доказательств или юридических обязательств. Вы можете запросить полное удаление с помощью support@circuitcourt.com. Технические журналы хранятся ограниченный период времени."},{heading:"Ваши права",body:"У вас есть право доступа, исправления, удаления, ограничения, возражения и переноса. Вы можете воспользоваться этими правами, написав по адресу support@circuitcourt.com. Вы также можете подать жалобу в CNIL (www.cnil.fr)."},{heading:"Файлы cookie и локальное хранилище",body:"Сервис использует только необходимое локальное хранилище: сеанс Firebase, выбранный язык, список покупок и информацию о версии. Мы не используем рекламные файлы cookie или инструменты измерения аудитории. Если это изменится, ваше согласие будет запрошено до внесения каких-либо несущественных депозитов."}]},terms:{title:"Условия эксплуатации",sections:[{heading:"Цель услуги",body:"Circuit Court — это местная служба поиска и сравнения продуктов. Он соединяет потребителей и производителей. Circuit Court не обрабатывает продажи, заказы, платежи, поставки или бронирования."},{heading:"Учетная запись пользователя",body:"Вы должны предоставить точную информацию, сохранять конфиденциальность своих учетных данных и быть не моложе 16 лет. Вы несете ответственность за действия, происходящие с вашей учетной записью, и должны незамедлительно уведомлять нас о любом несанкционированном использовании."},{heading:"Обязанности производителей",body:"Производители должны публиковать точные сведения о продуктах, ценах, количествах и наличии, соблюдать правила, применимые к их продукции и их деятельности, и не предлагать какие-либо незаконные товары. Они несут полную ответственность за соответствие, качество и безопасность своей продукции."},{heading:"Допустимое использование",body:"Запрещено массово извлекать данные, нарушать работу сервиса, выдавать себя за третье лицо, публиковать ложную или вводящую в заблуждение информацию или использовать платформу в незаконных целях. Аккаунт может быть заблокирован в случае злоупотреблений."},{heading:"Отношения между пользователями",body:"Любые отношения, резервирование или продажа, заключенные между потребителем и производителем, заключаются непосредственно между ними. Circuit Court не является стороной данных соглашений и не гарантирует наличие, цену или качество рекламируемых продуктов."},{heading:"Ответственность и интеллектуальная собственность",body:"Услуга предоставляется «как есть», в пределах разумных усилий и обязательных положений законодательства. Бренды, тексты, изображения и программное обеспечение Circuit Court остаются защищенными. Любое несанкционированное воспроизведение запрещено."},{heading:"Эволюция и применимое право",body:"Эти условия могут измениться; онлайн-версия является подлинной. Они подчиняются французскому законодательству. По любым вопросам обращайтесь по support@circuitcourt.com."}]},notice:{title:"Юридические уведомления",sections:[{heading:"Редактор",body:"Сайт опубликован Circuit Court. Контакт: support@circuitcourt.com. Регистрационную информацию и почтовый адрес издателя можно получить по запросу по этому адресу."},{heading:"Направление публикации",body:"Публикацией управляет представитель Circuit Court, с которым можно связаться по support@circuitcourt.com."},{heading:"Размещение",body:"Статический сайт размещен на хосте GitHub Pages (GitHub Inc., 88 Colin P Kelly Jr St, Сан-Франциско, Калифорния 94107, США). Служба приложения размещается в инфраструктуре, контролируемой издателем, и предоставляется через ngrok."},{heading:"Интеллектуальная собственность",body:"Содержание, бренды, тексты, изображения и программные элементы сайта защищены законом об интеллектуальной собственности. Любое несанкционированное воспроизведение или повторное использование запрещено."},{heading:"Персональные данные",body:"Обработка персональных данных описана в политике конфиденциальности. Чтобы воспользоваться своими правами, напишите на support@circuitcourt.com."}]},cookies:{title:"Политика использования файлов cookie",sections:[{heading:"Что мы храним",body:"Circuit Court использует технические файлы cookie и локальное хранилище браузера для работы службы. Эти элементы не используются для отслеживания вас в рекламных целях."},{heading:"Основное хранилище",body:"Мы храним сеанс аутентификации Firebase, выбранный язык, ваш список покупок, настройки поиска и информацию о версии. Без этих элементов служба не может функционировать должным образом."},{heading:"Измерение аудитории и реклама",body:"В настоящее время мы не используем рекламные файлы cookie или инструменты измерения аудитории. Если мы добавим их, мы отобразим баннер согласия, и вы сможете отказаться от несущественных файлов cookie."},{heading:"Сторонние сервисы",body:"Аутентификация Firebase (Google) может устанавливать файлы cookie или локальное хранилище, необходимые для входа в систему. GitHub Pages и ngrok обрабатывают технические журналы при доступе к сайту и API."},{heading:"Управление хранилищем",body:"Вы можете удалить файлы cookie и локальное хранилище в настройках браузера или выйти из системы, чтобы очистить сеанс. Удаление необходимого хранилища может потребовать от вас повторного входа в систему и повторного входа в список покупок."}]}},N={updated:K,docs:U},M="2026-11-17",R={privacy:{title:"Ture no te oraraa taa ê",sections:[{heading:"Taata faatere haamaramaramaraa",body:"E hopoi'a na Circuit Court no te faatere i te mau haamaramaramaraa no ni'a ia'na iho i faataahia i roto i teie ture. A papa'i i te support@circuitcourt.com no te mau uiraa e aore râ, te mau aniraa atoa."},{heading:"Te mau haamaramaramaraa i putuputuhia",body:"E faaohipa matou i ta outou vahi nohoraa e te Firebase ID, te mau haamaramaramaraa no ni'a i te taata hamani (te i'oa, te vahi nohoraa, te mau haamaramaramaraa no ni'a i te niuniu paraparau, te tahua itenati, e te rata uira), te vahi i faaohipahia no te maimiraa, te mau mea e vai ra i roto i ta outou mau tabula hooraa tao'a tei tape'ahia i roto i ta outou matini roro uira, ta outou mau poro'i e te mau buka faahororaa e titauhia no te faatereraa e te parururaa o te taviniraa."},{heading:"Te mau opuaraa e te mau niu ture",body:"E faaohipahia teie mau haamaramaramaraa no te horoa i te taviniraa, no te haapapu i te mau moni, no te faaite i te feia hamani hoho'a i pihai iho mai, no te pahono i te mau poroi, e no te paruru i te tahua itenati. Te mau niu ture, o te raveraa ïa i te parau faaau, to tatou anaanatae ti'a no te paruru e no te haamaitai i te taviniraa, to outou fariiraa i te mau paraparauraa ma'itihia, e te haapa'oraa i ta tatou mau titauraa i mua i te ture."},{heading:"Te feia farii e te mau faahororaa",body:"E nehenehe te feia horo'a e faatere nei e e faatere nei i te taviniraa e farii i te mau haamaramaramaraa, mai ia Google Firebase no te haapapûraa, GitHub Pages no te tahua itenati, ngrok no te fariiraa i te rave'a haaparareraa, e Mailgun no te tonoraa i te mau rata uira. Eiaha matou e hoo atu i ta outou mau haamaramaramaraa. E nehenehe te tahi mau taata horoa e faaohipa i te mau haamaramaramaraa i rapae atu i te Autahoêraa no Europa ma te faaohipa i te mau parau faaau tano."},{heading:"Te tape'araa e te iritiraa",body:"E tape'ahia te mau haamaramaramaraa no ni'a i te moni no te roaraa o te faaohiparaa i te taviniraa. I teie nei, ua riro te iritiraa i te hoê moni ei tapao no te iritiraa: ua hunahia te hoho'a, tera râ, e nehenehe te reni e tapeahia no te mau tumu no te parururaa, te mau haapapûraa, aore ra te mau titauraa a te ture. support@circuitcourt.com e nehenehe ta outou e ani i te iritiraa taatoa. E tapeahia te mau buka faahororaa no te hoê tau taa ê."},{heading:"To outou mau ti'araa",body:"E ti'araa to outou ia farii, ia faati'a, ia iriti, ia taoti'a, ia pato'i e ia afa'i. E nehenehe ta outou e faaohipa i teie mau ti'araa na roto i te papa'iraa i te support@circuitcourt.com. E nehenehe atoa outou e hapono i te hoê amuamu ia CNIL (www.cnil.fr)."},{heading:"Te mau cookies e te vahi tape'araa",body:"E faaohipa noa te taviniraa i te mau vahi tape'araa e titauhia: te tuhaa pureraa Firebase, te reo i ma'itihia, te tabula hooraa, e te mau haamaramaramaraa no ni'a i te mau huriraa. Aita matou e faaohipa nei i te mau cookies aore ra te mau ravea no te faito i te feia e faaroo ra. Mai te mea e, e taui te reira, e anihia to outou mana'o hou a tuuhia ' i te mau haaputuraa moni e ere i te mea faufaa rahi."}]},terms:{title:"Te mau ture no te faaohiparaa",sections:[{heading:"Te tumu o te taviniraa",body:"Ua riro te Circuit Court ei taviniraa no te ite e no te faaau i te mau tao'a no te fenua iho. E tuati te reira i te feia hoo e te feia hamani. Aita te Circuit Court e faatere ra i te mau hooraa, mau faaueraa, mau aufauraa, mau hooraa, aore ra mau tapura."},{heading:"Taata faaohipa",body:"E mea ti'a ia outou ia horo'a i te mau haamaramaramaraa ti'a, ia tape'a huna noa i to outou mau ti'aturiraa, e ia 16 matahiti a'e to outou. E hopoia na outou no te ohipa e tupu ra i roto i ta outou moni e e tia ia outou ia faaara oioi ia matou no nia i te mau faaohiparaa aita i fariihia."},{heading:"Te mau hopoia a te feia hamani hoho'a",body:"E tia i te feia hamani ia nenei i te mau tao'a, te mau hoo, te rahiraa e te vai - maitai - raa, ia pee i te mau ture e faaohipahia no ta ratou mau tao'a e ta ratou ohipa, e eiaha e horoa i te mau tao'a tia ore. E hopoia noa ratou no te huru, te huru, e te parururaa o ta ratou mau tao'a."},{heading:"Faaohiparaa fariihia",body:"E mea opanihia ia titau i te mau haamaramaramaraa rahi, ia haafifi i te taviniraa, ia haavare i te toru o te taata, ia nenei i te mau haamaramaramaraa haavare aore ra haavare, aore ra ia faaohipa i te tahua itenati no te mau opuaraa tia ore. E nehenehe te hoê moni e tapeahia mai te peu e e hamani - ino - hia te reira."},{heading:"Te mau taairaa i rotopu i te feia faaohipa",body:"Te mau taairaa atoa, te mau tapearaa, aore ra te mau hooraa i rotopu i te hoê taata hoo e te hoê taata hamani hoho'a, e faaotihia ïa i rotopu ia raua. E ere te Circuit Court i te hoê melo o teie mau faaauraa e aita oia e haapapu ra i te vai - maitai - raa, te hoo, aore ra te huru o te mau tao'a i faaitehia."},{heading:"Te hopoi'a e te mau tao'a aravihi",body:"E horoahia te taviniraa mai te reira te huru, i roto i te mau otia o te mau tutavaraa tura e te mau ture titauhia. E paruru - noa - hia te mau tapao, te mau papa'iraa, te mau hoho'a, e te mau rave'a haaparareraa a Circuit Court. E opanihia te mau neneiraa atoa aita i fariihia."},{heading:"Te tauiraa e te ture e faaohipahia ra",body:"E nehenehe teie mau huru tupuraa e taui; E mea papû te huriraa i ni'a i te itenati. E auraro ratou i te ture Farani. A niuniu ia support@circuitcourt.com no te mau uiraa atoa."}]},notice:{title:"Te mau faaararaa ture",sections:[{heading:"Papa'i parau",body:"Ua nene'ihia teie tahua itenati e Circuit Court. Horo'a: support@circuitcourt.com. E roaa te mau haamaramaramaraa no nia i te faanahoraa e te vahi nohoraa o te taata nenei i teie vahi nohoraa."},{heading:"Arata'iraa no te papa'iraa",body:"E faaterehia te buka e te ti'a no Circuit Court, i support@circuitcourt.com."},{heading:"Te vahi faaearaa",body:"GitHub Pages (GitHub Pages, 88 Colin P Kelly Jr St, CA 94107, united states) o te faatere nei i te tahua itenati. E tuuhia te ohipa faaohiparaa i ni'a i te hoê rave'a faaterehia e te taata nene'i e e faaitehia na roto i te ngrok."},{heading:"Te mau tao'a maramarama",body:"E paruruhia te mau mea e vai ra i roto, te mau tapao, te mau papa'iraa, te mau hoho'a, e te mau rave'a roro uira o te tahua itenati e te ture no te mau tao'a aravihi. E opanihia te neneiraa aore ra te faaohiparaa faahou aita i fariihia."},{heading:"Ngaahi haamaramaramaraa o te taata iho",body:"Te faataahia ra te faaohiparaa i te mau haamaramaramaraa a te taata iho i roto i te ture no te mau ohipa huna. A papa'i i te support@circuitcourt.com no te faaohipa i to outou mau ti'araa."}]},cookies:{title:"Ture cookie",sections:[{heading:"Te mau mea ta tatou e tape'a nei",body:"No te faatere i te taviniraa, e faaohipa te Circuit Court i te mau kuki aravihi e te mau rave'a haaparareraa parau no te fenua iho. Aita teie mau hu'ahu'a e faaohipahia no te hi'opo'a ia outou no te mau opuaraa faatianiani."},{heading:"Te vahi tape'araa faufaa",body:"Te tape'a nei matou i te tuhaa pureraa Firebase, te reo i ma'itihia, ta outou tapura hooraa, te mau hinaaro no te imiraa, e te mau haamaramaramaraa no ni'a i te huriraa. Eita te taviniraa e nehenehe e ohipa maitai mai te peu e aita teie mau mea."},{heading:"Te faitoraa o te feia mataitai e te mau parau faatiani",body:"I teie nei, aita matou e faaohipa nei i te mau cookies aore ra te mau ravea no te faito i te feia e faaroo ra. Mai te mea e, e tuu tatou i te tahi, e faaite tatou i te hoê reva mana'o, e e nehenehe ta outou e pato'i i te mau kuki e ere i te mea faufaa rahi."},{heading:"Te toru o te pŭpŭ",body:"E nehenehe te faati'araa Firebase (Google) e taui i te mau kuki e aore râ, te mau vahi tape'araa e titauhia no te tomo. Ia tomo ana'e o GitHub Pages e o ngrok i ni'a i te tahua itenati e te API, e faaohipa ïa ratou i te mau buka faahororaa."},{heading:"A faatere i te vahi tapearaa",body:"I roto i ta outou mau faanahoraa mata'ita'iraa, e nehenehe ta outou e tamau i te mau cookies e te mau vahi tape'araa, e aore râ, e tomo i rapae no te iriti i te tuhaa pureraa. E titau paha outou ia tomo faahou e ia tomo faahou i roto i ta outou tapura hooraa no te iriti i te mau vahi tape'araa faufaa."}]}},W={updated:M,docs:R},n={en:m,fr:y,de:v,es:P,pt:E,id:F,ja:I,zh:H,ar:V,ru:N,ty:W};function Z(e){return n[e]||n.fr}const Y=["privacy","terms","notice","cookies"],$=["privacy","terms","notice","cookies"];function r(){const e=window.location.hash.match(/^#legal\/(privacy|terms|notice|cookies)$/);return e?e[1]:""}const i=l(r());function o(){i.value=r()}function O(e="privacy"){const a=$.includes(e)?e:"privacy";i.value=a,window.history.replaceState(null,"",`${window.location.pathname}${window.location.search}#legal/${a}`)}function B(){i.value="",window.history.replaceState(null,"",`${window.location.pathname}${window.location.search}`)}function _(){return d(()=>{o(),window.addEventListener("hashchange",o)}),c(()=>{window.removeEventListener("hashchange",o)}),{legalDoc:i,openLegal:O,closeLegal:B}}const Q=(e,a)=>{const t=e.__vccOpts||e;for(const[s,u]of a)t[s]=u;return t};export{Y as L,Q as _,Z as g,O as o,_ as u};
